
'use strict';

const MANIFEST = 'flutter-app-manifest';
const TEMP = 'flutter-temp-cache';
const CACHE_NAME = 'flutter-app-cache';

// Keep your original RESOURCES object exactly as generated by Flutter.
const RESOURCES = {
  // PASTE YOUR ORIGINAL RESOURCES OBJECT HERE
};

// Flutter application shell.
const CORE = [
  'main.dart.js',
  'index.html',
  'flutter.js',
  'flutter_bootstrap.js',
  'assets/AssetManifest.bin.json',
  'assets/FontManifest.json'
];

// GitHub Pages base path, e.g. /monazeem/
const BASE_URL = new URL(self.registration.scope);
const BASE_PATH = BASE_URL.pathname;

function resourceURL(key) {
  return new URL(key === '/' ? './' : key, BASE_URL).href;
}

function normalizeKey(url) {
  const parsed = new URL(url);
  if (parsed.origin !== BASE_URL.origin) return null;
  if (!parsed.pathname.startsWith(BASE_PATH)) return null;

  let key = parsed.pathname.substring(BASE_PATH.length);

  if (key === '') key = '/';

  return key;
}

// INSTALL
self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const tempCache = await caches.open(TEMP);

    const results = await Promise.allSettled(
      Object.keys(RESOURCES).map(async (key) => {
        const url = resourceURL(key);

        const response = await fetch(
          new Request(url, { cache: 'reload' })
        );

        if (!response.ok) {
          throw new Error(`Failed to download ${key}`);
        }

        await tempCache.put(url, response);
      })
    );

    const failed = [];

    results.forEach((result, index) => {
      if (result.status === 'rejected') {
        failed.push(Object.keys(RESOURCES)[index]);
        console.error('Cache download failed:', failed[failed.length - 1],
          result.reason);
      }
    });

    const missingCore = CORE.filter((key) =>
      failed.includes(key)
    );

    if (missingCore.length) {
      await caches.delete(TEMP);
      throw new Error(
        'Essential Flutter files failed to download: ' +
        missingCore.join(', ')
      );
    }

    await self.skipWaiting();
  })());
});

// ACTIVATE
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    try {
      const contentCache = await caches.open(CACHE_NAME);
      const tempCache = await caches.open(TEMP);
      const manifestCache = await caches.open(MANIFEST);

      const oldManifestResponse = await manifestCache.match('manifest');

      const oldManifest = oldManifestResponse
        ? await oldManifestResponse.json()
        : {};

      // Remove only outdated or unknown resources.
      for (const request of await contentCache.keys()) {
        const key = normalizeKey(request.url);

        if (
          key === null ||
          !RESOURCES[key] ||
          RESOURCES[key] !== oldManifest[key]
        ) {
          await contentCache.delete(request);
        }
      }

      // Move newly downloaded files into the main cache.
      for (const request of await tempCache.keys()) {
        const response = await tempCache.match(request);
        if (response) {
          await contentCache.put(request, response);
        }
      }

      await caches.delete(TEMP);

      // Save the new manifest.
      await manifestCache.put(
        'manifest',
        new Response(JSON.stringify(RESOURCES))
      );

      // Remove legacy caches from earlier experiments.
      const cacheNames = await caches.keys();

      await Promise.all(
        cacheNames
          .filter((name) =>
            name.startsWith('flutter-offline-monazeem-')
          )
          .map((name) => caches.delete(name))
      );

      await self.clients.claim();

      console.log('Flutter offline cache activated.');

    } catch (error) {
      console.error('Service worker activation failed:', error);
      throw error;
    }
  })());
});

// FETCH: CACHE FIRST
self.addEventListener('fetch', (event) => {
  const request = event.request;

  if (request.method !== 'GET') return;

  const key = normalizeKey(request.url);

  if (key === null) return;

  // Ignore query parameters when identifying resources.
  const cleanKey = key.split('?v=')[0];

  const isNavigation = request.mode === 'navigate';

  const resourceKey =
    Object.prototype.hasOwnProperty.call(RESOURCES, cleanKey)
      ? cleanKey
      : isNavigation
        ? 'index.html'
        : null;

  if (!resourceKey) return;

  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const cachedResponse = await cache.match(
      resourceURL(resourceKey)
    );

    // Offline-first: return the cached version immediately.
    if (cachedResponse) {
      return cachedResponse;
    }

    // Fallback to network only when the resource isn't cached.
    try {
      const response = await fetch(request);

      if (response.ok) {
        await cache.put(
          resourceURL(resourceKey),
          response.clone()
        );
      }

      return response;

    } catch (error) {
      console.error('Offline resource unavailable:', resourceKey);

      return new Response(
        'Application resource unavailable offline.',
        {
          status: 503,
          headers: {
            'Content-Type': 'text/plain'
          }
        }
      );
    }
  })());
});

// MESSAGE
self.addEventListener('message', (event) => {
  if (event.data === 'skipWaiting') {
    self.skipWaiting();
  }

  if (event.data === 'downloadOffline') {
    event.waitUntil(downloadOffline());
  }
});

// DOWNLOAD OFFLINE
async function downloadOffline() {
  const cache = await caches.open(CACHE_NAME);

  const missingResources = [];

  for (const key of Object.keys(RESOURCES)) {
    const cached = await cache.match(resourceURL(key));

    if (!cached) {
      missingResources.push(key);
    }
  }

  for (const key of missingResources) {
    const response = await fetch(
      new Request(resourceURL(key), {
        cache: 'reload'
      })
    );

    if (!response.ok) {
      throw new Error('Failed to download: ' + key);
    }

    await cache.put(resourceURL(key), response);
  }

  console.log('Offline download completed.');
}
